llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C76"],
      "claim": "Propranolol, a close aryloxypropanolamine analogue (transfer 0.9882), has absolute oral bioavailability averaging 60% (range 38-85%) in humans, directly supporting F >= 20% for the query's similar beta-blocker scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Metoprolol, another aryloxypropanolamine beta-blocker (transfer 0.9866), has absolute oral bioavailability of 38 ± 14% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Timolol, which shares the tert-butylamino-hydroxypropoxy motif with the query (transfer 0.9864), has absolute oral bioavailability of 61.0 ± 19.2% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Flecainide (transfer 0.9863), a polar aryl ether/amide with a basic center, has oral bioavailability greater than 90% in normal subjects, supporting high F for the query despite polar and ionizable groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Safinamide (transfer 0.9872), an aryl ether/amide with a basic amino group, has absolute oral bioavailability of 95% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "One healthy-volunteer study reported propranolol oral bioavailability of 19%, showing that first-pass metabolism in this beta-blocker class can occasionally drop F below 20%; this is outweighed by the central tendency and other high-transfer analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Direct human absolute-bioavailability data for close beta-blocker analogues (propranolol, metoprolol, timolol) and structurally related polar drugs (flecainide, safinamide) consistently show F >= 20%, often 40-95%. The query's aryloxypropanolamine core and tert-butylamine match these high-F scaffolds; the added urea/cyclohexyl polarity is a concern but not sufficient to predict F < 20%. The physicochemical prior is mixed/unclear and is overridden by transferable experimental evidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "The effect of the additional urea/cyclohexyl group on permeability and first-pass metabolism is not directly measured.",
    "Transporter-mediated efflux and metabolic stability of the tert-butylamine/urea combination are not assessed.",
    "Most analogue data are from healthy subjects; disease-state effects on F are not directly applicable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

